create table if not exists public.coupons(id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,code text not null,description text,discount_type text not null default 'fixed',discount_value numeric(12,2) not null default 0,min_order_amount numeric(12,2) not null default 0,max_discount_amount numeric(12,2),usage_limit integer,usage_count integer not null default 0,per_customer_limit integer,start_at timestamptz,end_at timestamptz,is_active boolean not null default true,created_by uuid references public.app_users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(business_id,code));
alter table public.coupons enable row level security; revoke all on public.coupons from anon,authenticated; grant select,insert,update,delete on public.coupons to authenticated;
create policy coupons_tenant on public.coupons for all to authenticated using(business_id=(select private.current_business_id())) with check(business_id=(select private.current_business_id()));
create trigger trg_coupons_updated_at before update on public.coupons for each row execute function public.touch_updated_at();
create table if not exists public.cash_registers(id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,branch_id bigint references public.branches(id) on delete set null,opened_by uuid references public.app_users(id) on delete set null,closed_by uuid references public.app_users(id) on delete set null,status text not null default 'open',opened_at timestamptz not null default now(),closed_at timestamptz,opening_balance numeric(14,2) not null default 0,closing_balance numeric(14,2),expected_balance numeric(14,2),cash_sales numeric(14,2) not null default 0,cash_refunds numeric(14,2) not null default 0,cash_in numeric(14,2) not null default 0,cash_out numeric(14,2) not null default 0,notes text,metadata jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create unique index if not exists cash_registers_one_open_per_branch on public.cash_registers(business_id,coalesce(branch_id,0)) where status='open';
alter table public.cash_registers enable row level security; revoke all on public.cash_registers from anon,authenticated; grant select,insert,update,delete on public.cash_registers to authenticated;
create policy cash_registers_tenant on public.cash_registers for all to authenticated using(business_id=(select private.current_business_id())) with check(business_id=(select private.current_business_id()));
create trigger trg_cash_registers_updated_at before update on public.cash_registers for each row execute function public.touch_updated_at();